146	OB_INLINE int64_t ObTenantDfc::get_max_size_per_channel()
147	{
148	  //这里不原子拿，因为仅仅估算，感觉没有必要保证原子性
149	  int64_t tmp_total_cnt = channel_total_cnt_;
150	  int64_t tmp_blocked_dfc_cnt = blocked_dfc_cnt_;
151	  //并发不一致可能导致小于0
152	  tmp_blocked_dfc_cnt = tmp_total_cnt <= tmp_blocked_dfc_cnt ? tmp_total_cnt : tmp_blocked_dfc_cnt;
153	  int64_t tmp_unblock_dfc_cnt = tmp_total_cnt - tmp_blocked_dfc_cnt;
154	  tmp_total_cnt = 0 == tmp_total_cnt ? 1 : tmp_total_cnt;
155	  int64_t max_parallel_cnt = (0 == max_parallel_cnt_) ? 1 : max_parallel_cnt_;
156	  // 这里是为了限制一个channel使用了太多buffer
157	  int64_t tmp_max_size_per_channel = max_blocked_buffer_size_ / max_parallel_cnt * 2;
158	  int64_t max_size_per_channel = max_blocked_buffer_size_ / tmp_total_cnt * 8 / 10;
159	  if (0 != tmp_total_cnt && 0 != tmp_blocked_dfc_cnt) {
160	    max_size_per_channel = max_blocked_buffer_size_ * (1 + tmp_unblock_dfc_cnt * 8 / 10 / tmp_blocked_dfc_cnt) / tmp_total_cnt;
161	  }
162	  if (max_size_per_channel > tmp_max_size_per_channel) {
163	    max_size_per_channel = tmp_max_size_per_channel;
164	  }
165	  return max_size_per_channel;
