170	OB_INLINE bool ObTenantDfc::need_block(ObDtlFlowControl *dfc)
171	{
172	  // first judge whether current dfc need block, reduce concurrent effects
173	  // then judge whether global server need block
174	  bool need_block = false;
175	  if (nullptr != dfc && dfc->need_block()) {
176	    int64_t max_size_per_dfc = get_max_size_per_channel() * dfc->get_channel_count();
177	    need_block = dfc->get_used() >= max_size_per_dfc || tenant_dfc_.get_used() >= max_buffer_size_;
178	  #ifdef ERRSIM
